 "content": "from collections import deque


def transform(grid):
    """List the colors of non-background objects in descending color order."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    background = max(counts, key=counts.get)
    seen = set()
    colors = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or grid[r][c] == background:
                continue
            color = grid[r][c]
            colors.append(color)
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny,nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny,nx))
                        q.append((ny,nx))
    colors.sort(reverse=True)
    colors = (colors + [0] * 6)[:6]
    return [colors[:3], colors[3:]]
